let selectedCategory='All templates', selectedId=null, selectedIsCustom=false;
const $=id=>document.getElementById(id); const customKey='ednv_custom_templates_v1', favKey='ednv_favorites_v1', globalKey='ednv_global_overrides_v1';
let publishedOverrides={};
async function loadPublishedOverrides(){try{const r=await fetch('./global-overrides.json?ts='+Date.now());if(r.ok)publishedOverrides=await r.json()}catch{} renderCategories();renderTemplates()}
function readGlobal(){try{return JSON.parse(localStorage.getItem(globalKey)||'{}')}catch{return {}}} function writeGlobal(v){localStorage.setItem(globalKey,JSON.stringify(v))}
function readCustom(){try{return JSON.parse(localStorage.getItem(customKey)||'[]')}catch{return []}}function writeCustom(v){localStorage.setItem(customKey,JSON.stringify(v))}function readFav(){try{return JSON.parse(localStorage.getItem(favKey)||'[]')}catch{return []}}function writeFav(v){localStorage.setItem(favKey,JSON.stringify(v))}
function allTemplates(){const overrides={...publishedOverrides,...readGlobal()};return [...templates.map(t=>overrides[t.id]?({...t,...overrides[t.id],globalOverride:true}):t),...readCustom().map(t=>({...t,custom:true}))]}
function renderCategories(){const nav=$('categories');nav.innerHTML='';categories.forEach(cat=>{const b=document.createElement('button');b.className='nav-button'+(selectedCategory===cat?' active':'');b.innerHTML=`<span>${cat}</span><span class="count">${categoryCount(cat)}</span>`;b.onclick=()=>{selectedCategory=cat;renderCategories();renderTemplates();$('editor-panel').classList.add('hidden');$('custom-panel').classList.add('hidden')};nav.appendChild(b)});}
function categoryCount(cat){const list=allTemplates();if(cat==='All templates')return list.length;if(cat==='Favorites')return list.filter(t=>readFav().includes(t.id)).length;if(cat==='My templates')return readCustom().length;return list.filter(t=>t.category===cat).length}
function renderTemplates(){const q=$('search').value.trim().toLowerCase();let list=allTemplates().filter(t=>{const catOK=selectedCategory==='All templates'||(selectedCategory==='Favorites'?readFav().includes(t.id):selectedCategory==='My templates'?t.custom:t.category===selectedCategory);return catOK&&(!q||`${t.title} ${t.category} ${t.desc} ${t.body}`.toLowerCase().includes(q))});$('page-title').textContent=selectedCategory;$('page-subtitle').textContent=`${list.length} template${list.length===1?'':'s'} · Select a card to preview and edit.`;const grid=$('template-list');grid.innerHTML='';if(!list.length){grid.innerHTML='<div class="empty">No templates found. Try another search or add a custom template.</div>';return}list.forEach(t=>{const b=document.createElement('button');b.className='template-card';const isFav=readFav().includes(t.id);b.innerHTML=`<div><span class="pill">${escapeHtml(t.category)}</span> ${isFav?'<span class="star">★</span>':''}</div><h3>${escapeHtml(t.title)}</h3><p>${escapeHtml(t.desc||'Custom clinical template')}</p><div class="card-bottom"><span>${t.custom?'CUSTOM':'ED TEMPLATE'}</span><span>Open →</span></div>`;b.onclick=()=>openTemplate(t.id);grid.appendChild(b)})}
function escapeHtml(s){return String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]))}
function openTemplate(id){const t=allTemplates().find(x=>x.id===id);if(!t)return;selectedId=id;selectedIsCustom=!!t.custom;$('editor-category').textContent=t.category;$('editor-title').textContent=t.title;$('editor-desc').textContent=t.desc||'';$('note-text').value=t.body;$('favorite-note').textContent=readFav().includes(id)?'★ Favorited':'☆ Favorite';$('save-custom').textContent=t.custom?'Update personal template':'Save personal copy';$('status').textContent='';$('editor-panel').classList.remove('hidden');$('custom-panel').classList.add('hidden');$('editor-panel').scrollIntoView({behavior:'smooth',block:'start'})}
function closeEditor(){$('editor-panel').classList.add('hidden');selectedId=null}
$('search').addEventListener('input',renderTemplates);$('close-editor').onclick=closeEditor;$('copy-note').onclick=async()=>{const txt=$('note-text').value;try{await navigator.clipboard.writeText(txt);$('status').textContent='Copied to clipboard.'}catch{const ta=$('note-text');ta.select();const ok=document.execCommand('copy');$('status').textContent=ok?'Copied to clipboard.':'Select the text and copy manually.'}};
$('reset-note').onclick=()=>{const t=allTemplates().find(x=>x.id===selectedId);if(t&&confirm('Reset edits to the original template?')){$('note-text').value=t.body;$('status').textContent='Template reset.'}};
$('favorite-note').onclick=()=>{if(!selectedId)return;let f=readFav();f=f.includes(selectedId)?f.filter(x=>x!==selectedId):[...f,selectedId];writeFav(f);$('favorite-note').textContent=f.includes(selectedId)?'★ Favorited':'☆ Favorite';renderCategories();renderTemplates()};
$('save-custom').onclick=()=>{if(!selectedId)return;const current=allTemplates().find(t=>t.id===selectedId);const list=readCustom();const saved={id:current.custom?current.id:`custom-${Date.now()}`,title:current.title,category:current.category,desc:current.desc,body:$('note-text').value};if(current.custom){const idx=list.findIndex(t=>t.id===current.id);if(idx>=0)list[idx]=saved;else list.push(saved)}else{saved.title=`${current.title} (Custom)`;list.push(saved)}writeCustom(list);selectedCategory='My templates';renderCategories();renderTemplates();$('status').textContent='Saved in this browser.'};
$('save-global').onclick=()=>{if(!selectedId)return;const current=allTemplates().find(t=>t.id===selectedId);if(!current||current.custom){$('status').textContent='Global updates are for built-in templates. Save this as a personal template instead.';return}const overrides=readGlobal();overrides[selectedId]={title:current.title,category:current.category,desc:current.desc,body:$('note-text').value};writeGlobal(overrides);$('status').textContent='Global change saved on this browser. Click Export global updates, then upload global-overrides.json to GitHub to publish it across devices.';renderTemplates()};
$('export-global').onclick=()=>{const overrides=readGlobal();if(!Object.keys(overrides).length){$('status').textContent='No global changes saved yet.';return}const blob=new Blob([JSON.stringify(overrides,null,2)],{type:'application/json'});const url=URL.createObjectURL(blob);const a=document.createElement('a');a.href=url;a.download='global-overrides.json';a.click();URL.revokeObjectURL(url);$('status').textContent='Downloaded global-overrides.json. Upload it to the root of your GitHub repository and commit the change.'};
$('new-template').onclick=()=>{$('custom-panel').classList.remove('hidden');$('editor-panel').classList.add('hidden');$('custom-title').value='';$('custom-desc').value='';$('custom-body').value='';$('custom-category').innerHTML=categories.filter(c=>!['All templates','Favorites','My templates'].includes(c)).map(c=>`<option>${escapeHtml(c)}</option>`).join('');$('custom-panel').scrollIntoView({behavior:'smooth',block:'start'})};$('close-custom').onclick=()=>$('custom-panel').classList.add('hidden');$('create-custom').onclick=()=>{const title=$('custom-title').value.trim(),body=$('custom-body').value.trim();if(!title||!body){alert('Please enter a title and template text.');return}const list=readCustom();list.push({id:`custom-${Date.now()}`,title,category:$('custom-category').value,desc:$('custom-desc').value.trim(),body});writeCustom(list);$('custom-panel').classList.add('hidden');selectedCategory='My templates';renderCategories();renderTemplates()};
renderCategories();renderTemplates();
// Re-render after the first paint as a safeguard against delayed layout/script timing.
if (document.readyState === 'loading') {
  document.addEventListener('DOMContentLoaded', () => { renderCategories(); renderTemplates(); }, { once: true });
} else {
  requestAnimationFrame(() => { renderCategories(); renderTemplates(); });
}
loadPublishedOverrides();
